{
  "families": [
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 24, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 0.35,
      "why": "1 result/cycle gives the throughput needed to drain an 8-request burst inside the 0.4 us p99 budget, and large m cuts the per-stage register count, which is the main lever on the luts_plus_ffs objective."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 24, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "k", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 0.35,
      "why": "Shared datapath with k chained micro-rotations/cycle should be the cheapest way to reach the ~20 Msps burst-drain rate; large k is the candidate low-area corner of the front, so it needs a wide k sweep."
    },
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 24, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.2,
      "why": "Fully registered pipeline is the highest-Fmax, lowest-latency option and anchors the fast end of the front; it is the m=1 reference against which pipelined_m area savings are measured."
    },
    {
      "family": "iterative",
      "ranges": [
        {"param": "data_width", "low": 10, "high": 24, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.1,
      "why": "Smallest-area family, so it would dominate the luts_plus_ffs objective if it could meet the burst latency; a small probe is enough to confirm whether N+3 cycles/result can ever drain a burst of 8 within 0.4 us."
    }
  ],
  "rationale": "The binding constraints are accuracy (max_abs_err <= 2^-10, which needs roughly N>=11-13 and W>=12) and the system p99 latency of 0.4 us for bursts of 8 requests arriving 0 ns apart. Draining 8 requests in under 400 ns needs either 1 result/cycle (pipelined, pipelined_m) or a large unroll factor (unrolled_k with k near 8), so those three families get most of the budget; iterative is probed only to check the low-area corner. data_width 10..24 and n_iter 8..20 bracket the accuracy-feasible region without wasting evaluations on clearly infeasible low widths, and the guard/rounding parameters are left at full range because they trade accuracy against area at fixed W and N. Round 1 is deliberately broad so later rounds can narrow onto the families and parameter bands that actually populate the front."
}

{
  "decision": "refine",
  "next_plan": {
    "families": [
      {
        "budget_share": 0.7,
        "family": "pipelined_m",
        "ranges": [
          {"choices": ["trunc", "round"], "high": null, "low": null, "param": "rounding"},
